    /// <param name="options">Additional parameters.
    /// <list type="bullet">
    ///     <item>
    ///         <term><see
    ///         cref="VisualizeIsochroneRequest.Options.SOLVE_TABLE">SOLVE_TABLE</see>:
    ///         </term>
